 func NewReservationService(repo repository.ReservationRepository, features repository.FeatureRepository, bookings reservationBookingWriter, broker *OrderEventBroker) *ReservationService {
+	// A missing broker is a wiring mistake, and it is said HERE rather than at the
+	// write: by then the row is committed, so refusing would cost the guest a
+	// reservation the database already holds. Startup is the only moment the
+	// complaint is both loud and free.
+	if broker == nil {
+		log.Error().Msg("reservation: constructed without an event broker, booking.created will reach no terminal")
+	}
 	return &ReservationService{repo: repo, features: features, bookings: bookings, broker: broker}
 }
